mapper.select:
SELECT t.COUNTER_TRADER code FROM ( SELECT DISTINCT etr.COUNTER_TRADER FROM ETR_ENTRUST_ADD etr_add INNER JOIN ETR_ENTRUST etr ON etr.ENTRUST_ID = etr_add.ENTRUST_ID
AND etr.COUNTER_ID = #{counterId}
) t
t.COUNTER_TRADER like concat('%',concat(#{param},'%'))

SELECT TEMP.*, NVL(TEMP.ptlPositionsNum,0) * NVL(TEMP.price,0) - NVL(TEMP.positionsAmt,0) floatingPL FROM ( SELECT TEMP.PORTFOLIO_ID AS portfolioId, PP.PORTFOLIO_NAME AS portfolioName, TEMP.SEC_ACCT_ID AS secAcctId, SSAI.SEC_ACCT_NAME AS secAcctName, TEMP.FINPROD_ID AS finprodId, FP.FINPROD_MARKET_ID AS finprodMarketId, CASE WHEN instr(FP.FINPROD_MARKET_ID,'.') > 0 THEN SUBSTR(FP.FINPROD_MARKET_ID,1,instr(FP.FINPROD_MARKET_ID,'.',-1,1)-1) ELSE FP.FINPROD_MARKET_ID END AS secId, FP.FINPROD_ABBR AS secName, TEMP.AMOUNT AS positionsNum, ESP.AMOUNT AS sellNum, CASE WHEN FP.FINPROD_TYPE2 = #{FINPROD_TYPE_TG_F01} THEN MBVI.NETPRICE WHEN FP.FINPROD_TYPE2 = #{FINPROD_TYPE_TG_F06} THEN MFMI.CLOSE_PRICE WHEN FP.FINPROD_TYPE2 = #{FINPROD_TYPE_TG_F10} THEN MSP.CLOSE_PRICE ELSE NULL END AS price, CASE WHEN (NVL(T2.SHARE_AMT,0)+PSP.AMOUNT)=0 THEN NVL(PSV.DSC_COST_AMT,0)+NVL(T1.TRADE_AMT,0) ELSE ((NVL(PSV.DSC_COST_AMT,0)+NVL(T1.TRADE_AMT,0)) - (NVL(T2.SHARE_AMT,0)*(NVL(PSV.DSC_COST_AMT,0)+NVL(T1.TRADE_AMT,0))/(NVL(T2.SHARE_AMT,0)+PSP.AMOUNT))) END AS positionsAmt, PSP.AMOUNT AS ptlPositionsNum,
FP.FINPROD_TYPE2 AS finprodType2, FP.TRADE_MARKET AS tradeMarket, SSAI.TRD_ACCT_ID AS acctNo FROM ( SELECT PSP.CDATE AS CDATE, PSP.PORTFOLIO_ID AS PORTFOLIO_ID , PSP.SEC_ACCT_ID AS SEC_ACCT_ID , PSP.FINPROD_ID AS FINPROD_ID, PSP.BRANCH AS BRANCH, SUM(CASE WHEN PSP.HODING_TYPE IN (#{POSITION_TYPE_03}, #{POSITION_TYPE_05}) THEN NVL(PSP.AMOUNT,0) ELSE -1* NVL(PSP.AMOUNT,0) END) AS AMOUNT FROM PTL_SEC_POSITION PSP INNER JOIN PTL_PORTFOLIO PP ON PSP.PORTFOLIO_ID = PP.PORTFOLIO_ID INNER JOIN PTL_PORTFOLIO_AUTHORITY PPA ON PP.PORTFOLIO_ID = PPA.PORTFOLIO_ID
AND PPA.USER_ID = #{userId}
WHERE PSP.BRANCH =0 AND PSP.HODING_TYPE IN (#{POSITION_TYPE_03}, #{POSITION_TYPE_04}, #{POSITION_TYPE_05}, #{POSITION_TYPE_06}) AND PSP.CDATE = #{sysDate} GROUP BY PSP.CDATE, PSP.PORTFOLIO_ID , PSP.SEC_ACCT_ID, PSP.FINPROD_ID, PSP.BRANCH )TEMP LEFT JOIN ( SELECT T.PORTFOLIO_ID, T.SEC_ACCT_ID, T.FINPROD_ID, T.BRANCH, T.CDATE, SUM(T.AMOUNT) AMOUNT FROM ETR_SEC_POSITION T GROUP BY T.PORTFOLIO_ID, T.SEC_ACCT_ID, T.FINPROD_ID, T.BRANCH, T.CDATE ) ESP ON TEMP.PORTFOLIO_ID = ESP.PORTFOLIO_ID AND TEMP.SEC_ACCT_ID = ESP.SEC_ACCT_ID AND TEMP.FINPROD_ID = ESP.FINPROD_ID AND TEMP.BRANCH = ESP.BRANCH AND TEMP.CDATE = ESP.CDATE LEFT JOIN FIN_PRODUCT FP ON TEMP.FINPROD_ID = FP.FINPROD_ID
LEFT JOIN MST_BOND_VALUATION_INFO MBVI ON FP.FINPROD_MARKET_ID = MBVI.SEC_ID AND MBVI.VALUE_DATE <= #{sysDate} AND MBVI.VALUE_SOURCE = #{VALUATION_SOURCE_CSD} LEFT JOIN (SELECT MAX(MBVI2.VALUE_DATE) VALUE_DATE, MBVI2.SEC_ID,MBVI2.VALUE_SOURCE FROM MST_BOND_VALUATION_INFO MBVI2 WHERE MBVI2.VALUE_DATE <= #{sysDate} AND MBVI2.VALUE_SOURCE = #{VALUATION_SOURCE_CSD} GROUP BY MBVI2.SEC_ID,MBVI2.VALUE_SOURCE) MBVTTMP ON MBVI.VALUE_DATE = MBVTTMP.VALUE_DATE AND MBVI.SEC_ID = MBVTTMP.SEC_ID AND MBVI.VALUE_SOURCE = MBVTTMP.VALUE_SOURCE
LEFT JOIN MST_FUND_MARKET_INFO MFMI ON FP.FINPROD_MARKET_ID = MFMI.FUND_CODE AND MFMI.VALUE_DATE <= #{sysDate} LEFT JOIN (SELECT MAX(MFMI2.VALUE_DATE) VALUE_DATE, MFMI2.FUND_CODE FROM MST_FUND_MARKET_INFO MFMI2 WHERE MFMI2.VALUE_DATE <= #{sysDate} GROUP BY MFMI2.FUND_CODE) MFMITMP ON MFMI.VALUE_DATE = MFMITMP.VALUE_DATE AND MFMI.FUND_CODE = MFMITMP.FUND_CODE
LEFT JOIN MST_SHARE_PRICE MSP ON FP.FINPROD_MARKET_ID = MSP.SHARES_ID AND MSP.DEAL_DATE <= #{sysDate} LEFT JOIN (SELECT MAX(MSP2.DEAL_DATE) DEAL_DATE, MSP2.SHARES_ID FROM MST_SHARE_PRICE MSP2 WHERE MSP2.DEAL_DATE <= #{sysDate} GROUP BY MSP2.SHARES_ID) MSPTMP ON MSP.SHARES_ID = MSPTMP.SHARES_ID AND MSP.DEAL_DATE = MSPTMP.DEAL_DATE LEFT JOIN ( SELECT T.PORTFOLIO_ID, T.SEC_ACCT_ID, T.FINPROD_ID, T.CDATE, SUM(T.DSC_COST_AMT) DSC_COST_AMT FROM PTL_SEC_VALUTION T WHERE T.CDATE = #{sysDate} - 1 GROUP BY T.PORTFOLIO_ID, T.SEC_ACCT_ID, T.FINPROD_ID, T.CDATE ) PSV ON TEMP.PORTFOLIO_ID = PSV.PORTFOLIO_ID AND TEMP.SEC_ACCT_ID = PSV.SEC_ACCT_ID AND TEMP.FINPROD_ID = PSV.FINPROD_ID AND PSV.CDATE = #{sysDate} - 1 LEFT JOIN ( SELECT TPD.FINPROD_ID, TPD.SEC_MANAGE_ACCT_ID, TPDA.PORTFOLIO_ID, SUM(NVL(TPD.TRADE_AMT,0)) AS TRADE_AMT, SUM(NVL(TPD.SHARE_AMT,0)) AS SHARE_AMT FROM TRD_PRODUCT_DEAL TPD LEFT JOIN TRD_PRODUCT_DEAL_ADD TPDA ON TPDA.TRADE_ID = TPD.TRADE_ID WHERE ( ( TPD.PS IN ( #{PS_T01}, #{PS_T46}, #{PS_T97}, #{PS_T04}) AND TPD.FINPROD_TYPE2 IN(#{FINPROD_TYPE_TG_F01}, #{FINPROD_TYPE_TG_F10}) ) OR ( TPD.PS IN ( #{PS_T01}, #{PS_T05}) AND TPD.FINPROD_TYPE2 IN(#{FINPROD_TYPE_TG_F06}) ) ) AND TPD.CHL_ID IS NULL AND TPD.TRADE_DATE = #{sysDate} GROUP BY TPD.FINPROD_ID, TPD.SEC_MANAGE_ACCT_ID, TPDA.PORTFOLIO_ID ) T1 ON TEMP.PORTFOLIO_ID = T1.PORTFOLIO_ID AND TEMP.SEC_ACCT_ID = T1.SEC_MANAGE_ACCT_ID AND TEMP.FINPROD_ID = T1.FINPROD_ID LEFT JOIN ( SELECT TPD.FINPROD_ID AS FINPROD_ID , TPD.SEC_MANAGE_ACCT_ID AS SEC_MANAGE_ACCT_ID, TPDA.PORTFOLIO_ID AS PORTFOLIO_ID, SUM(NVL(TPD.SHARE_AMT,0)) AS SHARE_AMT FROM TRD_PRODUCT_DEAL TPD LEFT JOIN TRD_PRODUCT_DEAL_ADD TPDA ON TPDA.TRADE_ID = TPD.TRADE_ID WHERE TPD.PS IN ( #{PS_T02}, #{PS_T03}, #{PS_T19} ) AND TPD.FINPROD_TYPE2 IN(#{FINPROD_TYPE_TG_F01}, #{FINPROD_TYPE_TG_F06}, #{FINPROD_TYPE_TG_F10}) AND TPD.CHL_ID IS NULL AND TPD.TRADE_DATE = #{sysDate} GROUP BY TPD.FINPROD_ID , TPD.SEC_MANAGE_ACCT_ID , TPDA.PORTFOLIO_ID ) T2 ON TEMP.PORTFOLIO_ID = T2.PORTFOLIO_ID AND TEMP.SEC_ACCT_ID = T2.SEC_MANAGE_ACCT_ID AND TEMP.FINPROD_ID= T2.FINPROD_ID LEFT JOIN ( SELECT T.PORTFOLIO_ID, T.SEC_ACCT_ID, T.FINPROD_ID, T.BRANCH, T.CDATE, SUM(T.AMOUNT) AMOUNT FROM PTL_SEC_POSITION T WHERE T.BRANCH=0 AND T.HODING_TYPE IN (#{POSITION_TYPE_03}) AND T.CDATE = #{sysDate} GROUP BY T.PORTFOLIO_ID, T.SEC_ACCT_ID, T.FINPROD_ID, T.BRANCH, T.CDATE ) PSP ON TEMP.PORTFOLIO_ID = PSP.PORTFOLIO_ID AND TEMP.SEC_ACCT_ID = PSP.SEC_ACCT_ID AND TEMP.FINPROD_ID = PSP.FINPROD_ID AND TEMP.BRANCH = PSP.BRANCH AND TEMP.CDATE = PSP.CDATE LEFT JOIN PTL_PORTFOLIO PP ON TEMP.PORTFOLIO_ID = PP.PORTFOLIO_ID LEFT JOIN STL_SEC_ACCT_INFO SSAI ON TEMP.SEC_ACCT_ID = SSAI.SEC_ACCT_ID WHERE FP.TRADE_MARKET IN (#{TRADE_PLACE_03}, #{TRADE_PLACE_04}) AND FP.FINPROD_TYPE2 = #{FINPROD_TYPE_TG_F01}
#{portfolioId,jdbcType=VARCHAR}
AND FP.TRADE_MARKET = #{tradeMarket,jdbcType=VARCHAR}
AND TEMP.SEC_ACCT_ID = #{secAcctId,jdbcType=VARCHAR}
AND FP.FINPROD_MARKET_ID = #{finprodId,jdbcType=VARCHAR}
) TEMP

select trd_product_deal_add.portfolio_id portfolioId, /** 组合代码 **/ PTL_PORTFOLIO.PORTFOLIO_NAME portfolioName, /** 组合名称 **/ FIN_PRODUCT_TYPE.Type_7 as ps, /** 交易方向 **/ case when trd_fin_product_deal_total.totle_trade_id is not null then '已购回' else '未购回' end as purStatus, /** 购回状态 **/
fin_trade_product.TERM repDays, /** 回购天数 **/ fin_trade_product.Mdate backDate, /** 回购到期日 **/ fin_trade_product.Trade_Market market, /** 市场 **/ /*fin_deal_pledge.pledge_finprod_id stockCode,*/ /** 质押券代码 **/ nvl(fp.FINPROD_NAME,fp.FINPROD_ABBR) stockName, nvl(fp.FINPROD_MARKET_ID,fin_deal_pledge.pledge_finprod_id) stockCode, fin_deal_pledge.Pledge_Ratio * 100 discountRate, /** 折算率 **/ fin_deal_pledge.Pledge_Number repSecNum, /** 质押券数量 **/ fin_deal_pledge.Pledge_Face_Value * fin_deal_pledge.Pledge_Number pledStrdPrinAmt, /** 质押券面总额 **/ fin_trade_product.Prin tradeAmt, /** 回购金额 **/ fin_trade_product.INT_RATE * 100 yield, /** 回购利率 **/ fin_trade_product.vpay_date fristSettleDate, /** 首次结算日 **/ fin_trade_product.mpay_date expireSettleDate, /** 到期结算日 **/ fin_trade_product.act_cap_days occupyDays, /** 实际占款天数 **/ fin_trade_product.m_int_amt mIntAmt, /** 回购利息 **/ fin_trade_product.m_Trade_Amt expireSettleAmt, /** 到期结算金额 **/ decode(fin_trade_product.TRADE_MARKET,'03',trd_product_deal_2.f_trade_id,'04','') tradeId, /** 成交编号 **/ decode(fin_trade_product.TRADE_MARKET,'03','','04',trd_product_deal_2.f_trade_id) intiTradeId /** 初始交易编号 **/ from fin_trade_product /** 交易类金融产品 **/ inner join FIN_PRODUCT_TYPE /** 金融产品分类表 **/ on fin_trade_product.finprod_id = FIN_PRODUCT_TYPE.Finprod_Id and fin_trade_product.BRANCH = FIN_PRODUCT_TYPE.Branch and FIN_PRODUCT_TYPE.Type_6 = 'H01' AND FIN_PRODUCT_TYPE.TYPE_7 in ('03', '04') INNER JOIN trd_product_deal trd_product_deal_2 /** 金融产品临时交易 **/ on fin_trade_product.finprod_id = trd_product_deal_2.Finprod_Id and fin_trade_product.branch = trd_product_deal_2.branch and trd_product_deal_2.ps in ('T01') and trd_product_deal_2.is_cancel = 'N' and trd_product_deal_2.trade_status = '01' LEFT JOIN trd_product_deal_add /** 金融产品临时交易附属表 **/ on trd_product_deal_2.trade_id = trd_product_deal_add.trade_id left join fin_deal_pledge /** 回购质押品 **/ on fin_trade_product.finprod_id = fin_deal_pledge.finprod_id AND fin_trade_product.branch = fin_deal_pledge.branch left join FIN_PRODUCT fp on fp.finprod_id = fin_deal_pledge.pledge_finprod_id LEFT JOIN PTL_PORTFOLIO /** 组合 **/ on trd_product_deal_add.Portfolio_Id = PTL_PORTFOLIO.Portfolio_Id LEFT JOIN trd_fin_product_deal_total trd_fin_product_deal_total /** 金融产品临时交易1 **/ on fin_trade_product.finprod_id = trd_fin_product_deal_total.finprod_id AND fin_trade_product.branch = trd_fin_product_deal_total.branch AND trd_fin_product_deal_total.ps in ('T54', 'T07', 'T93', 'T56') LEFT JOIN PTL_PORTFOLIO_AUTHORITY /** 组合权限表 **/ ON PTL_PORTFOLIO.Portfolio_Id = PTL_PORTFOLIO_AUTHORITY.Portfolio_Id where fin_trade_product.branch = '0' AND fin_trade_product.trade_market IN ('03', '04')
AND fin_trade_product.finprod_id = #{tradeId,jdbcType=VARCHAR}
AND PTL_PORTFOLIO_AUTHORITY.USER_ID = #{userId}

select distinct * from ( select etr_entrust.entrust_id entrustId, /** 指令编号 **/ etr_entrust.entrust_status entrustStatus, /** 指令状态 **/ nvl(case WHEN etr_entrust.PS IN ('T93', 'T94') AND NULLIF(0, etr_pledge.PLEDGE_NUMBER) IS NOT NULL THEN CASE WHEN ROUND((etr_finish_status.ORDER_FINISH_AMT/ etr_pledge.PLEDGE_NUMBER),4) >=1 THEN 1 ELSE ROUND((etr_finish_status.ORDER_FINISH_AMT/ etr_pledge.PLEDGE_NUMBER),4) END when NULLIF(0, etr_entrust.ENTRUST_AMT) is not null then ROUND((etr_finish_status.ORDER_FINISH_AMT/etr_entrust.ENTRUST_AMT),4) END,0) implementPercent, /** 执行进度 **/ nvl(case WHEN etr_entrust.PS IN ('T93', 'T94') AND NULLIF(0, etr_pledge.PLEDGE_NUMBER) IS NOT NULL THEN CASE WHEN ROUND((etr_finish_status.Ent_Finish_Amt/ etr_pledge.PLEDGE_NUMBER),4) >=1 THEN 1 ELSE ROUND((etr_finish_status.Ent_Finish_Amt/ etr_pledge.PLEDGE_NUMBER),4) END when NULLIF(0, etr_entrust.ENTRUST_AMT) is not null then case when ROUND((etr_finish_status.Ent_Finish_Amt/etr_entrust.ENTRUST_AMT),4)>=1 then 1 else ROUND((etr_finish_status.Ent_Finish_Amt/etr_entrust.ENTRUST_AMT),4) end END,0) dealPercent, /** 执行进度 **/
PTL_PORTFOLIO.Portfolio_Id portfolioId, /** 组合代码 **/ PTL_PORTFOLIO.Portfolio_Name portfolioName, /** 组合名称 **/ SCI.ACCT_NAME dealCurAcct, /** 资金账户 **/
etr_entrust.trade_market tradeMarket, /** 市场 **/ etr_entrust.Trade_Plat tradePlat, /** 交易平台 **/ etr_entrust.Ps ps, /** 交易方向 **/ etr_entrust_add.Term_Days term,/** 回购期限 **/ etr_entrust.entrust_amt entrustAmt, /** 回购金额 **/ etr_entrust.Price price, /** 回购利率 **/ etr_entrust_add.vpay_date fristSettleDate,/** 首期结算日 **/ etr_entrust_add.mpay_date expireSettleDate,/** 到期结算日 **/ etr_entrust_add.Cap_Days occupyDays,/** 占款天数 **/ etr_entrust_add.m_Int_Amt intAmt,/** 回购利息 **/ etr_entrust_add.m_Trade_Amt expireSettleAmt,/** 到期结算金额 **/ etr_pledge.finprod_id finprodId, /** 金融产品代码 **/ fin_product.Finprod_Market_Id finprodMarketId, /** 质押代码 **/ fin_product.finprod_abbr finprodAbbr, /** 质押券名称 **/ etr_pledge.Pledge_Ratio * 100 conRatio, /** 折算率 **/ etr_pledge.PLEDGE_NUMBER repSecNum,/** 质押数量 **/ etr_pledge.PLEDGE_NUMBER * etr_pledge.Pledge_Face_Value printAmt, /** 质押面额 **/ etr_entrust_add.Sec_Acct_Id secAcctId, /** 证券账户 ※隐藏 **/ etr_entrust.counter_id counterId, /** 交易对手 **/ mst_counter_party.counter_name counterName, /**交易对手名称**/ etr_entrust.counter_trader counterTrader,/** 对手方交易员 **/ etr_entrust.vdate vdate,/** 开始日期 **/ etr_entrust.mdate mdate/** 结束日期 **/ ,etr_entrust.CREATE_TIME ,'' nextUser
from etr_entrust /** 委托指令 **/ inner JOIN etr_entrust_add /** 委托指令附属 **/ ON etr_entrust.entrust_id = etr_entrust_add.entrust_id LEFT JOIN etr_pledge /** 委托指令回购质押品 **/ ON etr_entrust.entrust_id = etr_pledge.entrust_id LEFT JOIN etr_finish_status /** 委托完成状况表 **/ ON etr_entrust.entrust_id = etr_finish_status.entrust_id and etr_entrust.entrust_id = etr_finish_status.trade_id LEFT JOIN PTL_PORTFOLIO /** 组合 **/ ON etr_entrust.portfolio_id = PTL_PORTFOLIO.Portfolio_Id LEFT JOIN PTL_PORTFOLIO_AUTHORITY /** 组合权限表 **/ ON PTL_PORTFOLIO.Portfolio_Id = PTL_PORTFOLIO_AUTHORITY.Portfolio_Id LEFT JOIN fin_product /** 标的类金融产品 **/ ON fin_product.finprod_id = etr_entrust.finprod_id LEFT JOIN mst_counter_party /** 交易对手 **/ ON etr_entrust.counter_id = mst_counter_party.counter_id LEFT JOIN STL_CAPACCT_INFO SCI ON etr_entrust_add.Deal_Cur_Acct = SCI.ACCT_NO where etr_entrust.TRADE_MARKET IN ('03','04') and etr_entrust_add.ASSET_TYPE1 = 'H01'
AND etr_entrust.ENTRUST_STATUS = #{entrustStatus}
AND etr_entrust.ENTRUST_ID = #{entrustId}
AND PTL_PORTFOLIO_AUTHORITY.USER_ID = #{userId}
union all select wfl_etr_entrust.entrust_id entrustId, /** 指令编号 **/ '08' entrustStatus, /** 指令状态 **/ nvl(case WHEN wfl_etr_entrust.PS IN ('T93', 'T94') AND NULLIF(0, wfl_etr_pledge.PLEDGE_NUMBER) IS NOT NULL THEN CASE WHEN ROUND((etr_finish_status.ORDER_FINISH_AMT/ wfl_etr_pledge.PLEDGE_NUMBER),4) >=1 THEN 1 ELSE ROUND((etr_finish_status.ORDER_FINISH_AMT/ wfl_etr_pledge.PLEDGE_NUMBER),4) END when NULLIF(0, wfl_etr_entrust.ENTRUST_AMT) is not null then ROUND((etr_finish_status.ORDER_FINISH_AMT/wfl_etr_entrust.ENTRUST_AMT),4) END,0) implementPercent, /** 执行进度 **/ nvl(case WHEN wfl_etr_entrust.PS IN ('T93', 'T94') AND NULLIF(0, wfl_etr_pledge.PLEDGE_NUMBER) IS NOT NULL THEN CASE WHEN ROUND((etr_finish_status.Ent_Finish_Amt/ wfl_etr_pledge.PLEDGE_NUMBER),4) >=1 THEN 1 ELSE ROUND((etr_finish_status.Ent_Finish_Amt/ wfl_etr_pledge.PLEDGE_NUMBER),4) END when NULLIF(0, wfl_etr_entrust.ENTRUST_AMT) is not null then case when ROUND((etr_finish_status.Ent_Finish_Amt/wfl_etr_entrust.ENTRUST_AMT),4)>=1 then 1 else ROUND((etr_finish_status.Ent_Finish_Amt/wfl_etr_entrust.ENTRUST_AMT),4) end END,0) dealPercent, /** 执行进度 **/
PTL_PORTFOLIO.Portfolio_Id portfolioId, /** 组合代码 **/ PTL_PORTFOLIO.Portfolio_Name portfolioName, /** 组合名称 **/ SCI.ACCT_NAME dealCurAcct, /** 资金账户 **/
wfl_etr_entrust.trade_market tradeMarket, /** 市场 **/ wfl_etr_entrust.Trade_Plat tradePlat, /** 交易平台 **/ wfl_etr_entrust.Ps ps, /** 交易方向 **/ wfl_etr_entrust_add.Term_Days term,/** 回购期限 **/ wfl_etr_entrust.entrust_amt entrustAmt, /** 回购金额 **/ wfl_etr_entrust.Price price, /** 回购利率 **/ wfl_etr_entrust_add.vpay_date fristSettleDate,/** 首期结算日 **/ wfl_etr_entrust_add.mpay_date expireSettleDate,/** 到期结算日 **/ wfl_etr_entrust_add.Cap_Days occupyDays,/** 占款天数 **/ wfl_etr_entrust_add.m_Int_Amt intAmt,/** 回购利息 **/ wfl_etr_entrust_add.m_Trade_Amt expireSettleAmt,/** 到期结算金额 **/ wfl_etr_pledge.finprod_id finprodId, /** 金融产品代码 **/ fin_product.Finprod_Market_Id finprodMarketId, /** 质押代码 **/ fin_product.finprod_abbr finprodAbbr, /** 质押券名称 **/ wfl_etr_pledge.Pledge_Ratio * 100 conRatio, /** 折算率 **/ wfl_etr_pledge.PLEDGE_NUMBER repSecNum,/** 质押数量 **/ wfl_etr_pledge.PLEDGE_NUMBER * wfl_etr_pledge.Pledge_Face_Value printAmt, /** 质押面额 **/ wfl_etr_entrust_add.Sec_Acct_Id secAcctId, /** 证券账户 ※隐藏 **/ wfl_etr_entrust.counter_id counterId, /** 交易对手 **/ mst_counter_party.counter_name counterName, /**交易对手名称**/ wfl_etr_entrust.counter_trader counterTrader,/** 对手方交易员 **/ wfl_etr_entrust.vdate vdate,/** 开始日期 **/ wfl_etr_entrust.mdate mdate/** 结束日期 **/ ,wfl_etr_entrust.CREATE_TIME ,SWBL.NEXT_USER nextUser from wfl_etr_entrust inner JOIN wfl_etr_entrust_add ON wfl_etr_entrust.entrust_id = wfl_etr_entrust_add.entrust_id LEFT JOIN wfl_etr_pledge /** 委托指令回购质押品 **/ ON wfl_etr_entrust.entrust_id = wfl_etr_pledge.entrust_id LEFT JOIN etr_finish_status /** 委托完成状况表 **/ ON wfl_etr_entrust.entrust_id = etr_finish_status.entrust_id and wfl_etr_entrust.entrust_id = etr_finish_status.trade_id LEFT JOIN PTL_PORTFOLIO /** 组合 **/ ON wfl_etr_entrust.portfolio_id = PTL_PORTFOLIO.Portfolio_Id LEFT JOIN PTL_PORTFOLIO_AUTHORITY /** 组合权限表 **/ ON PTL_PORTFOLIO.Portfolio_Id = PTL_PORTFOLIO_AUTHORITY.Portfolio_Id LEFT JOIN fin_product /** 标的类金融产品 **/ ON fin_product.finprod_id = wfl_etr_entrust.finprod_id LEFT JOIN mst_counter_party /** 交易对手 **/ ON wfl_etr_entrust.counter_id = mst_counter_party.counter_id LEFT JOIN STL_CAPACCT_INFO SCI ON wfl_etr_entrust_add.Deal_Cur_Acct = SCI.ACCT_NO LEFT JOIN SYS_WFL_BUSINESS_LIST SWBL ON SWBL.SEQ_NO = wfl_etr_entrust.WORKFLOW_ID and SWBL.PROCESS_STATE != 'END' where wfl_etr_entrust.TRADE_MARKET IN ('03','04') and wfl_etr_entrust_add.ASSET_TYPE1 = 'H01'
AND wfl_etr_entrust.ENTRUST_STATUS = #{entrustStatus}
AND wfl_etr_entrust.ENTRUST_ID = #{entrustId}
AND PTL_PORTFOLIO_AUTHORITY.USER_ID = #{userId}
) T1 ORDER BY T1.CREATE_TIME DESC

select
max(t.cdate)
from etr_sec_position t
where
t.portfolio_id = #{portfolioId,jdbcType=VARCHAR}

    and t.sec_acct_id = #{secAcctId}


    and t.finprod_id = #{finprodId,jdbcType=VARCHAR}


    and t.branch = #{branch,jdbcType=DECIMAL}


    and t.INV_AIM = #{invAim}



    and t.INV_AIM != '999999'

and t.hoding_type = #{hodingType,jdbcType=VARCHAR}
and t.cdate <= #{cdate,jdbcType=DATE}

select
sum(t.amount) as amount
from etr_sec_position t
where
t.portfolio_id = #{portfolioId,jdbcType=VARCHAR}

    and t.sec_acct_id = #{secAcctId}


    and t.finprod_id = #{finprodId,jdbcType=VARCHAR}


    and t.branch = #{branch,jdbcType=DECIMAL}


    and t.INV_AIM = #{invAim}



    and t.INV_AIM != '999999'

and t.hoding_type = #{hodingType,jdbcType=VARCHAR}
and t.cdate = #{cdate,jdbcType=DATE}
